<script setup lang="ts">
import{reactive,ref,onMounted}from'vue';import{api}from'../api';import{useAuthStore}from'../stores/auth';const auth=useAuthStore(),rows=ref<any[]>([]),dialog=ref(false),editing=ref<number>();const form=reactive<any>({sku:'GPU-L40S-1',name:'L40S 推理型',gpuModel:'NVIDIA L40S',gpuCount:1,cpuCores:16,memoryGb:64,priceCent:19800,enabled:true});const load=async()=>rows.value=await api.get('/products');const open=(r?:any)=>{editing.value=r?.id;Object.assign(form,r||{sku:'GPU-L40S-1',name:'L40S 推理型',gpuModel:'NVIDIA L40S',gpuCount:1,cpuCores:16,memoryGb:64,priceCent:19800,enabled:true});dialog.value=true};const save=async()=>{editing.value?await api.put(`/products/${editing.value}`,form):await api.post('/products',form);dialog.value=false;load()};onMounted(load)
</script>
<template><div class="panel"><div class="toolbar"><div><el-input placeholder="搜索 SKU / 产品名称" style="width:260px" clearable/></div><el-button v-if="auth.can('product:manage')" type="primary" @click="open()">新增产品</el-button></div><el-table :data="rows"><el-table-column prop="sku" label="SKU" width="150"/><el-table-column prop="name" label="产品名称"/><el-table-column prop="gpuModel" label="GPU"><template #default="s">{{s.row.gpuModel}} × {{s.row.gpuCount}}</template></el-table-column><el-table-column label="规格"><template #default="s">{{s.row.cpuCores}} C / {{s.row.memoryGb}} GB</template></el-table-column><el-table-column label="价格"><template #default="s"><b class="money">¥{{(s.row.priceCent/100).toFixed(2)}}</b> / 次</template></el-table-column><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'在售':'停用'}}</el-tag></template></el-table-column><el-table-column v-if="auth.can('product:manage')" label="操作" width="80"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="editing?'编辑算力产品':'新增算力产品'" width="560"><el-form :model="form" label-width="90"><el-form-item label="SKU"><el-input v-model="form.sku" :disabled="!!editing"/></el-form-item><el-form-item label="产品名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="GPU 型号"><el-input v-model="form.gpuModel"/></el-form-item><el-form-item label="GPU 数量"><el-input-number v-model="form.gpuCount" :min="1"/></el-form-item><el-form-item label="CPU 核数"><el-input-number v-model="form.cpuCores" :min="1"/></el-form-item><el-form-item label="内存 GB"><el-input-number v-model="form.memoryGb" :min="1"/></el-form-item><el-form-item label="价格（分）"><el-input-number v-model="form.priceCent" :min="1"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
